/* ---------- Google Drive / Docs ---------- */
async function drive(url, opts) {
  const u = new URL(url);
  const m = u.pathname.match(/^\/(document|presentation|spreadsheets|file)\/(?:u\/\d+\/)?d\/([\w-]{10,})/);
  const type = m && m[1]; const id = (m && m[2]) || u.searchParams.get('id');
  if (!id) throw new SourceError('No reconozco ese enlace de Google Drive.');
  let target;
  if (type === 'document' || type === 'presentation') target = `https://docs.google.com/${type}/d/${id}/export?format=txt`;
  else if (type === 'spreadsheets') target = `https://docs.google.com/spreadsheets/d/${id}/export?format=csv`;
  else target = `https://drive.google.com/uc?export=download&id=${id}`;
  const r = await safeFetch(target, { headers: { 'user-agent': UA } }, { allow: (h) => hostIn(h, ['google.com', 'googleusercontent.com']), assertHost: opts.assertHost });
  const ct = (r.headers.get('content-type') || '').toLowerCase();
  const notPublic = new SourceError('No puedo abrir ese archivo: en Drive pulsa Compartir → «Cualquier persona con el enlace» (lector) y vuelve a pegarlo.', 403);
  if (r.status === 401 || r.status === 403 || r.status === 404) throw notPublic;
  const bytes = await readBody(r);
  if (ct.includes('text/html')) throw notPublic;
  const name = fileNameFrom(r, url, type ? 'Documento de Drive' : 'Archivo de Drive');
  if (/^text\//.test(ct) || ct.includes('csv')) return { title: name.replace(/\.(txt|csv)$/i, ''), text: cap(utf8(bytes)) };
  return { title: name, mime: ct.split(';')[0] || 'application/octet-stream', b64: b64(bytes) };
}

/* ---------- any web page ---------- */
async function web(url, opts) {
  const r = await safeFetch(url, { headers: { 'user-agent': UA, accept: 'text/html,application/pdf,text/plain,*/*;q=0.8', 'accept-language': 'es-ES,es;q=0.9,en;q=0.8' } }, { assertHost: opts.assertHost });
  if (r.status >= 400) throw new SourceError(`Ese sitio respondió con un error (${r.status}).`, 422);
  const ct = (r.headers.get('content-type') || '').toLowerCase();
  const bytes = await readBody(r);
  const name = fileNameFrom(r, url, 'Página web');
  if (ct.includes('application/pdf') || /^image\//.test(ct)) return { title: name, mime: ct.split(';')[0], b64: b64(bytes) };
  const cs = (/charset=([\w-]+)/i.exec(ct) || [])[1];
  let html = utf8(bytes, cs || 'utf-8');
  if (!cs) { const mc = /<meta[^>]+charset=["']?([\w-]+)/i.exec(html); if (mc && !/utf-?8/i.test(mc[1])) html = utf8(bytes, mc[1]); }
  if (!ct.includes('html')) return { title: name, text: cap(html) };
  const title = decodeEntities((/<title[^>]*>([\s\S]*?)<\/title>/i.exec(html) || [])[1] || '').replace(/\s+/g, ' ').trim() || new URL(url).hostname;
  const text = htmlToText(html);
  if (text.length < 200) throw new SourceError('Esa página casi no tiene texto legible (¿pide iniciar sesión o carga con JavaScript?). Copia el texto y pégalo.', 422);
  return { title, text: cap(`Página web: ${title}\n${url}\n\n${text}`) };
}

export async function getSource(kind, url, opts = {}) {
  if (!url || typeof url !== 'string' || url.length > 2000) throw new SourceError('Falta el enlace.');
  let u; try { u = new URL(url.trim()); } catch (e) { throw new SourceError('Ese enlace no es válido.'); }
  if (kind === 'youtube') { if (!hostIn(u.hostname, YT_HOSTS)) throw new SourceError('Eso no parece un enlace de YouTube.'); return youtube(u.href, opts.lang, opts); }
  if (kind === 'drive') { if (!hostIn(u.hostname, ['docs.google.com', 'drive.google.com'])) throw new SourceError('Eso no parece un enlace de Google Drive o Docs.'); return drive(u.href, opts); }
  if (kind === 'web') return web(u.href, opts);
  throw new SourceError('Tipo de fuente desconocido.');
}

// JSON response shared by every host (they only add the password check)
export async function sourceResponse(body, opts = {}) {
  const j = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store' } });
  try { return j(await getSource(body && body.kind, body && body.url, { ...opts, lang: body && body.lang })); }
  catch (e) { const known = e instanceof SourceError || (e && e.status && e.message); return j({ error: { message: known ? e.message : 'No se pudo leer ese enlace.' } }, known ? e.status : 500); }
}

/* ---------- Netlify wrapper ---------- */
const json = (obj, status) => new Response(JSON.stringify(obj), { status, headers: { 'content-type': 'application/json' } });

export default async (req) => {
  if (req.method !== 'POST') return json({ error: { message: 'Método no permitido' } }, 405);
  const password = Netlify.env.get('APP_PASSWORD');
  if (!password) return json({ error: { message: 'Falta APP_PASSWORD en las variables de entorno de Netlify.' } }, 500);
  if (req.headers.get('x-app-password') !== password) return json({ error: { message: 'Contraseña incorrecta' } }, 401);
  let body; try { body = await req.json(); } catch (e) { return json({ error: { message: 'Petición no válida' } }, 400); }
  return sourceResponse(body);
};

